 const scan=readScan(),saved=Array.isArray(scan?.out)?scan.out:[];
 if(!saved.length)throw new Error('保存済みの採用候補がありません');
 const n=Math.max(1,Math.min(saved.length,Number(maxCount)||saved.length));
 const seen=new Set(),rows=[];
