  if(!node.getClientRects?.().length||node.closest?.('#'+PANEL+',[id^="mumei-"],.ProseMirror'))continue;
  const text=String(node.textContent||'').trim();
  if(/^(?:(?:下書き|記事|本文|変更内容)を?|下書きとして|一時)?保存(?:しました|されました|済み)[。！!]?$/.test(text))notices.set(node,text);
