  const flush=()=>{if(!phrase.length)return;const whole=phrase.join('');parts.push(...(galleryProfileWidth(whole)<=maxWidth+.00001?[whole]:phrase));phrase=[]};
  for(const word of words){phrase.push(word);if(clause.test(word))flush()}
