async function restartFixed300(requestedOptions=null){
 if(busy||exportWaiter||coreBusy()){setStatus('実行中です。先に「停止」を押してください',true);return;}
 try{
  await Promise.all([hydrateRunBackup(),hydratePrepBackup()]);
  const options=requestedOptions||historyOptions(),run=readRun();
  if(run?.purchasedReview)throw new Error('購入記事紹介の作成中です。「購入記事紹介」の再開を使ってください');
  if(run?.awaitingInsertion){
   if(sameHistorySelection(run,options))return createFixed300();
   throw historySelectionError(null,'保存済みの作成条件が異なります。既存の作成記録を自動で消去しません');
  }
  if(run?.rows?.length){
   if(sameHistorySelection(run,options))return resumeFixed300();
   setStatus('現在の貼り付けの続きは「再開」を押してください',true);
   return;
  }
  const prep=readPrep();
  if(prep?.creatorIndex||options.creatorIndex&&prep?.rows?.length){
   if(prep.creatorIndex&&options.creatorIndex&&sameHistoryFilter(prep.historyFilter,options.historyFilter)&&prep.creatorIndexBridge?.people?.length)return createFixed300(options);
   throw historySelectionError(null,'この下書きには別の条件の読み込み記録があります。「再開」で続けられます');
  }
  return startFixed300(options);
 }catch(error){setStatus('取得停止：'+(error?.message||String(error)),true);}
}
async function resumeFixed300(){
 if(busy||exportWaiter||coreBusy()){setStatus('実行中です。先に「停止」を押してください',true);return;}
 try{
  await Promise.all([hydrateRunBackup(),hydratePrepBackup()]);
  if(page.__MUMEI_PROFILE_CARD_RESUME_MIXED_TAGS__?.({appendOnly:true}))return;
  if(readRun()?.pendingTagAppend){setStatus('今回追加した画像は0件です。新着の取得は①から始められます');return}
  const view=findView();if(view&&!readRun()?.magazineCardsOnly&&!readRun()?.creatorIndex)await repairTrackedRawFormulas(view);
  const run=readRun();
  if(run?.purchasedReview){setStatus('この保存分は購入記事紹介の専用版で再開してください',true);return;}
  if(run?.creatorIndex&&(run.creatorIndexCoverage!==2||run.creatorIndexHasGaps))return createFixed300();
  const resumeCards=page.__MUMEI_PROFILE_CARD_CREATE_CARDS_AT_TAP__;
  if(run?.magazineCardsOnly&&typeof resumeCards==='function')return resumeCards({resume:!run.awaitingInsertion,magazineSource:run.sources});
  if(hasCardProgress(run)&&!run.rows.some(summaryNeedsRefresh)&&!galleryNeedsParticipantUpgrade(run)&&typeof resumeCards==='function')return resumeCards({resume:true});
  if(page.__MUMEI_PROFILE_CARD_RESUME_MAGAZINE_MEMBERS__?.())return;
  if(!run?.gallery126&&run?.coreImageRun&&typeof page.__MUMEI_PROFILE_CARD_RESUME_CORE_IMAGES__==='function')return page.__MUMEI_PROFILE_CARD_RESUME_CORE_IMAGES__();
  if(run?.items?.length||run?.rows?.length)return createFixed300();
   if(page.__MUMEI_PROFILE_CARD_RESUME_MIXED_TAGS__?.())return;
  const saved=readPrep();
  if(saved?.articleLikes||saved?.creatorIndex)return createFixed300(checkpointHistoryOptions(saved));
  const bridge=await historyBridge();
  if(!Array.isArray(bridge?.people)||!bridge.people.length){setStatus('読み込みの続きがありません。「履歴から開始」でスキ履歴を取得してください',true);return;}
  setStatus('読み込みの続きから｜確認済み '+(saved?.rows?.length||0)+'人｜取得できない人は飛ばします');
  return createFixed300(checkpointHistoryOptions(saved,bridge));
 }catch(error){setStatus('読み込み再開停止：'+(error?.message||String(error)),true);}
}
